<?php
namespace App\Livewire;
use App\Models\AuditLog;use App\Models\FeeStructure;use App\Models\SchoolClass;use App\Models\StudentEnrolment;use App\Models\Term;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class Promotions extends Component {public string $sourceTermId='',$targetTermId='';public array $outcomes=[],$targetClasses=[];public function mount():void{$s=Auth::user()->school;$this->sourceTermId=(string)Term::where('school_id',$s->id)->where('status','closed')->latest('year')->value('id');$this->targetTermId=(string)Term::where('school_id',$s->id)->whereIn('status',['pending','open'])->orderBy('year')->value('id');}public function loadLearners():void{$classes=SchoolClass::where('school_id',Auth::user()->school_id)->orderBy('name')->get();foreach(StudentEnrolment::where(['school_id'=>Auth::user()->school_id,'term_id'=>$this->sourceTermId,'status'=>'active'])->get() as $e){$this->outcomes[$e->id]=$e->promotion_outcome?:'promoted';$i=$classes->search(fn($c)=>$c->id===$e->school_class_id);$this->targetClasses[$e->id]=(string)($classes->get($i===false?0:$i+1)?->id??$e->school_class_id);}}public function commit():void{$s=Auth::user()->school;$from=Term::where('school_id',$s->id)->findOrFail($this->sourceTermId);$to=Term::where('school_id',$s->id)->findOrFail($this->targetTermId);if($from->status!=='closed'||!in_array($to->status,['pending','open'],true)){session()->flash('error','Choose a closed source term and a pending/open target term.');return;}$rows=StudentEnrolment::with('student')->where(['school_id'=>$s->id,'term_id'=>$from->id,'status'=>'active'])->get();DB::transaction(function()use($s,$from,$to,$rows){foreach($rows as $e){$outcome=$this->outcomes[$e->id]??'promoted';$e->update(['promotion_outcome'=>$outcome]);if(in_array($outcome,['graduated','withdrawn'],true))continue;$classId=(int)($this->targetClasses[$e->id]??$e->school_class_id);$fee=FeeStructure::where(['school_id'=>$s->id,'term_id'=>$to->id,'school_class_id'=>$classId,'student_category_id'=>$e->student_category_id])->first();StudentEnrolment::updateOrCreate(['student_id'=>$e->student_id,'term_id'=>$to->id],['school_id'=>$s->id,'school_class_id'=>$classId,'stream_id'=>$e->stream_id,'student_category_id'=>$e->student_category_id,'fee_structure_id'=>$fee?->id,'base_fee_amount'=>$fee?->amount??0,'status'=>$to->isOpen()?'active':'pending','enrolled_at'=>now()->toDateString()]);if($to->isOpen())$e->student->update(['school_class_id'=>$classId,'term_id'=>$to->id]);}AuditLog::record($s->id,'term.promotions_committed',$from,['target_term_id'=>$to->id,'learners'=>$rows->count()]);});session()->flash('status','Promotion decisions committed.');}public function render(){$s=Auth::user()->school;return view('livewire.promotions',['terms'=>Term::where('school_id',$s->id)->latest('year')->get(),'classes'=>SchoolClass::where('school_id',$s->id)->orderBy('name')->get(),'enrolments'=>StudentEnrolment::with(['student','schoolClass'])->where(['school_id'=>$s->id,'term_id'=>$this->sourceTermId,'status'=>'active'])->get(),'pageTitle'=>'Promotions']);}}
